@override
def __call__(self, retry_state: "RetryCallState") -> bool:
    if retry_state.outcome is None:
        raise RuntimeError("__call__ called before outcome was set")

    if retry_state.outcome.failed:
        exc = retry_state.outcome.exception()
        # Guard against cyclic __cause__ chains (e.g. ``raise e from e``),
        # which would otherwise spin forever inside the predicate and
        # prevent stop conditions from ever running (see #658).
        seen: set[int] = set()
        while exc is not None and id(exc) not in seen:
            seen.add(id(exc))
            if isinstance(exc.__cause__, self.exception_cause_types):
                return True
            exc = exc.__cause__

    return False

def __getitem__(self, key):
    with self._lock:
        try:
            link = self._get_link_and_move_to_front_of_ll(key)
        except KeyError:
            self.miss_count += 1
            if not self.on_miss:
                raise
            ret = self[key] = self.on_miss(key)
            return ret

        self.hit_count += 1
        return link[VALUE]

def __setitem__(self, key, value):
    with self._lock:
        try:
            link = self._get_link_and_move_to_front_of_ll(key)
        except KeyError:
            if len(self) < self.max_size:
                self._set_key_and_add_to_front_of_ll(key, value)
            else:
                evicted = self._set_key_and_evict_last_in_ll(key, value)
                super().__delitem__(evicted)
        else:
            link[VALUE] = value
        super().__setitem__(key, value)
    return
